def get_content(language):
    """Return a complete catalog; unsupported language codes fall back to English."""
    language = language if language in LANGUAGE_NAMES else "en"
    index = {"es": 0, "fr": 1, "pt": 2}.get(language)
    messages = {key: key if index is None else values[index] for key, values in _MESSAGES.items()}
    return {**_CONTENT[language], "messages": messages}
